#!/usr/bin/env node
/**
 * FIXTURES — the recorded R309 run files the parity proof runs on, plus a lot lifecycle in the runner's own row shape. 2026-10-09
 * (docs/server/wave-r309fold). Generated by node only; the recorded files are BYTE COPIES (never re-serialized).
 *
 * RECORDED (fixtures/recorded/<day>/): R309's home copies at three points, exactly as recorded:
 *   2026-10-07   git a732d72c8 (nightly snapshot 2026-10-07): 6 live cycle rows, config.evidenceStart null, empty ledger
 *   2026-10-08   git 31f953273 (nightly snapshot 2026-10-08): 30 live cycle rows, evidenceStart "2026-10-08" (set on the VPS 10-08 15:02 UTC)
 *   2026-10-09   backend/data at build time (2026-10-09 ~13:08 MT pull): 52 live cycle rows; its sha256 is pinned in fixtures/index.json.
 *                That evening's git snapshot (105ce8d09, nightly snapshot 2026-10-09, 16:12 MT) is checked as its superset: the fixture's
 *                cycles an exact byte prefix of the committed file (54 rows), ledger equal (empty), evidenceStart / read equal
 *   Each later state's cycles file extends the earlier one byte for byte (append-only, as the VPS writes it). r309-interim.json was never
 *   written at home in this window (absent in all three); the ledger is empty in all three (R309 had not traded).
 * LIFECYCLE (fixtures/lifecycle.json): because no lot had been recorded yet, ten successive LEDGER states in the row shape
 *   backend/r309-surge-hold48.js writes (signal / twin / shadow / entry / exit legs / fees / notes; statuses submitting -> submitted ->
 *   open -> exiting -> closed, submit-error -> unfilled, not-sent, open -> error -> closed, and a missed row), with the signal values
 *   taken from recorded 2026-10-09 cycle rows (hour, close, return, sd, volume, 24 h high). Each state is a legal successor of the one
 *   before. Deterministic: --check rebuilds it in memory and compares.
 *
 *   node docs/server/wave-r309fold/fixtures.cjs --check      every fixture against index.json's sha256, the git-sourced ones against
 *                                                             `git show <commit>:<path>` (read-only), the prefix chain, lifecycle rebuilt
 *   node docs/server/wave-r309fold/fixtures.cjs --selftest   the same, as ok / FAIL lines
 *   node docs/server/wave-r309fold/fixtures.cjs --write      (build time) writes a recorded day only when ABSENT (recorded data is never
 *                                                             replaced), then lifecycle.json and index.json
 */
"use strict";
const fs = require("fs"), path = require("path"), cp = require("child_process"), crypto = require("crypto");
const HERE = __dirname, REPO = path.resolve(HERE, "..", "..", ".."), FX = path.join(HERE, "fixtures");
const sha = (b) => crypto.createHash("sha256").update(b).digest("hex");
const FILES = ["r309-cycles.jsonl", "r309-ledger.jsonl", "r309-surge-hold48.json", "r309-interim.json"];
const RECORDED = [
  { day: "2026-10-07", source: "git", commit: "a732d72c8", note: "nightly snapshot 2026-10-07" },
  { day: "2026-10-08", source: "git", commit: "31f953273", note: "nightly snapshot 2026-10-08" },
  { day: "2026-10-09", source: "home", note: "backend/data at build time (the 2026-10-09 13:08 MT pull); not yet in a git snapshot" },
];
/** the git snapshot taken the evening of the home-sourced 10-09 day: checked as its superset (never copied in: recorded data stays as recorded) */
const SNAP_0909 = { commit: "105ce8d09", note: "nightly snapshot 2026-10-09, 16:12 MT" };
const dayDir = (d) => path.join(FX, "recorded", d);
const atomicBytes = (f, b) => { fs.mkdirSync(path.dirname(f), { recursive: true }); const t = f + ".tmp-" + process.pid; fs.writeFileSync(t, b); fs.renameSync(t, f); };
function gitShow(commit, rel) {
  const r = cp.spawnSync("git", ["show", `${commit}:${rel}`], { cwd: REPO, maxBuffer: 256 << 20, windowsHide: true });
  if (r.error) throw new Error(`git unavailable (${r.error.message})`);
  return r.status === 0 ? r.stdout : null;   // null: the path does not exist at that commit
}
/** the recorded files of one day as Map name -> Buffer (absent files left out) */
function readDay(day, dir = dayDir(day)) { const m = new Map(); for (const f of FILES) { const p = path.join(dir, f); if (fs.existsSync(p)) m.set(f, fs.readFileSync(p)); } return m; }

// ── the lifecycle (pure; from recorded cycle rows) ───────────────────────────────────────────────────────────────────────────
const H = 3600000, iso = (ms) => new Date(ms).toISOString().replace(".000Z", "Z"), isoMs = (ms) => new Date(ms).toISOString();
/** a signal in the runner's shape (r309-surge-hold48.js `sig`), values from a recorded cycle row's coin block */
function signalFrom(row, coin) {
  const c = row.coins[coin], hourMs = Date.parse(row.evaluatedHour), id = `r309-${coin}-${row.evaluatedHour.slice(0, 13).replace(/[-T]/g, "")}`;
  const twinMs = hourMs - 37 * H;
  return { id, coin, signalHour: iso(hourMs), day: row.evaluatedHour.slice(0, 10), signalClose: c.close, stats: { ret: c.ret, sd: c.sd, vol: c.vol, medVol: c.medVol, hi24: c.hi24 },
    twin: { hour: iso(twinMs), seedKey: `${id}|twin`, seed: 1309, entryClose: +(c.close * 0.997).toFixed(2), exitHour: iso(twinMs + 48 * H), poolSize: 121, hoursBeforeSignal: 37, net: null },
    shadow: { exitHour: iso(hourMs + 48 * H), exitClose: null, net: null } };
}
function buildLifecycle(cyclesBuf) {
  const rows = cyclesBuf.toString("utf8").split("\n").filter((l) => l.trim()).map((l) => JSON.parse(l)).filter((r) => r.live && r.coins && r.coins.BTC && r.coins.BTC.ok && r.coins.ETH && r.coins.ETH.ok);
  if (rows.length < 12) throw new Error(`the recorded cycles hold ${rows.length} usable live rows (< 12)`);
  const host = rows[0].host, pick = (i) => rows[Math.min(rows.length - 1, i)], at = (r, min) => isoMs(Date.parse(r.ts) + min * 60000);
  const rA = pick(3), rB = pick(5), rM = pick(6), rC = pick(9), rD = pick(11);
  const A = signalFrom(rA, "BTC"), B = signalFrom(rB, "ETH"), M = signalFrom(rM, "ETH"), C = signalFrom(rC, "BTC"), D = signalFrom(rD, "ETH");
  const lot = (s, r) => ({ kind: "lot", ...s, host, status: "submitting", entry: { cid: `${s.id}-B`, notionalOrdered: 2000, submittedAt: at(r, 0.5) }, exit: { legs: [] }, fees: {}, notes: [] });
  const clone = (x) => JSON.parse(JSON.stringify(x));
  const fill = (l, r, px) => { const q = (2000 / px).toFixed(9); Object.assign(l.entry, { orderId: `ord-${l.id}-b`, status: "filled", filledQty: q, avgPx: px, filledAt: at(r, 0.6), slipBps: +((px / l.signalClose - 1) * 1e4).toFixed(2), notionalFilled: +(Number(q) * px).toFixed(2) }); l.status = "open"; return l; };
  const leg = (l, r, n) => ({ cid: `${l.id}-S${n}`, qty: l.entry.filledQty, submittedAt: at(r, 48 * 60 + 1), orderId: `ord-${l.id}-s${n}`, status: "filled", filledQty: l.entry.filledQty, avgPx: +(l.entry.avgPx * 1.012).toFixed(2), filledAt: at(r, 48 * 60 + 1.2) });
  const close = (l, r) => { const x = l.exit.legs[l.exit.legs.length - 1]; Object.assign(l.exit, { avgPx: x.avgPx, soldQty: x.filledQty, filledAt: x.filledAt }); l.gross = +(x.avgPx / l.entry.avgPx - 1).toFixed(6); l.net = +(l.gross - 0.005).toFixed(6); l.holdHours = +((Date.parse(x.filledAt) - Date.parse(l.entry.filledAt)) / H).toFixed(3); l.status = "closed"; l.closedAt = at(r, 48 * 60 + 2); l.twin.net = -0.0031; l.shadow.exitClose = +(l.signalClose * 1.01).toFixed(2); l.shadow.net = 0.0049; return l; };
  const states = []; const push = (label, list) => states.push({ label, rows: clone(list) });
  let a = lot(A, rA); push("A submitting", [a]);
  a.entry.orderId = `ord-${a.id}-b`; a.status = "submitted"; push("A submitted", [a]);
  fill(a, rA, +(A.signalClose * 1.0004).toFixed(2)); let b = lot(B, rB); push("A open; B submitting", [a, b]);
  b.status = "submit-error"; b.notes.push("submit: alpaca 503 /v2/orders (2 POST attempt(s); reconciled by client id)"); const m = { kind: "missed", ...M, reason: "entry window passed (10 min after the close)", at: at(rM, 11), host };
  push("B submit-error; M missed", [a, b, m]);
  a.fees.entry = { basis: "activities", feeQty: "0.000007500", ratio: 0.0025, usd: 5, rows: 1 }; a.exit.legs.push(leg(a, rA, 1)); a.exit.legs[0].status = "partially_filled"; a.exit.legs[0].filledQty = (Number(a.entry.filledQty) / 2).toFixed(9); a.status = "exiting"; b.status = "unfilled"; let c = lot(C, rC);
  push("A exiting; B unfilled; C submitting", [a, b, m, c]);
  a.exit.legs[0].status = "filled"; a.exit.legs[0].filledQty = a.entry.filledQty; c.status = "not-sent"; c.notes.push("no broker order under the client id 5+ minutes after the intent — not sent"); let d = lot(D, rD);
  push("A leg filled; C not-sent; D submitting", [a, b, m, c, d]);
  close(a, rA); fill(d, rD, +(D.signalClose * 0.9998).toFixed(2)); push("A closed; D open", [a, b, m, c, d]);
  d.status = "error"; d.notes.push(`${at(rD, 48 * 60 + 3)} exit leg sold nothing — a new leg follows`); push("D error", [a, b, m, c, d]);
  d.exit.legs.push(leg(d, rD, 1)); d.status = "exiting"; push("D exiting (from error)", [a, b, m, c, d]);
  close(d, rD); push("D closed", [a, b, m, c, d]);
  return { schema: "r309fold-lifecycle-v1", note: "Ledger states in backend/r309-surge-hold48.js's row shape; signal values from recorded 2026-10-09 cycle rows (fixtures/recorded/2026-10-09/r309-cycles.jsonl). No lot had been recorded when this was built (R309 had not traded): the shape is the runner's, the trades are not real.", fromCycles: { rows: rows.length, hours: [rA, rB, rM, rC, rD].map((r) => r.evaluatedHour) }, states };
}
const lifecycleBytes = (obj) => Buffer.from(JSON.stringify(obj, null, 1) + "\n");

// ── check ────────────────────────────────────────────────────────────────────────────────────────────────────────────────────
function check() {
  const res = []; const ok = (n, c, d) => res.push({ n, c: !!c, d });
  let idx = null; try { idx = JSON.parse(fs.readFileSync(path.join(FX, "index.json"), "utf8")); } catch (e) { ok("fixtures/index.json readable", false, e.message); return res; }
  ok("fixtures/index.json is an r309fold-fixtures-v1 index naming the three recorded days", idx.schema === "r309fold-fixtures-v1" && JSON.stringify(idx.recorded.map((d) => d.day)) === JSON.stringify(RECORDED.map((d) => d.day)));
  const days = {};
  for (const R of RECORDED) {
    const ent = idx.recorded.find((d) => d.day === R.day) || { files: {} }, m = readDay(R.day); days[R.day] = m;
    const names = [...m.keys()].sort(), want = Object.keys(ent.files).sort();
    ok(`recorded ${R.day}: the files present are the index's (${want.join(", ")})`, JSON.stringify(names) === JSON.stringify(want), names.join(","));
    ok(`recorded ${R.day}: every file's sha256 is the index's`, names.every((f) => sha(m.get(f)) === ent.files[f].sha256 && m.get(f).length === ent.files[f].bytes));
    if (R.source === "git") {
      let g = null, why = null;
      try { g = new Map(FILES.map((f) => [f, gitShow(R.commit, "backend/data/" + f)]).filter(([, b]) => b != null)); } catch (e) { why = e.message; }
      ok(`recorded ${R.day}: byte-equal to git ${R.commit} (${R.note}), file for file, absent where absent`, g && JSON.stringify([...g.keys()].sort()) === JSON.stringify(names) && names.every((f) => g.get(f).equals(m.get(f))), why || (g ? [...g.keys()].join(",") : ""));
    }
  }
  const c7 = days["2026-10-07"].get("r309-cycles.jsonl"), c8 = days["2026-10-08"].get("r309-cycles.jsonl"), c9 = days["2026-10-09"].get("r309-cycles.jsonl");
  const pre = (a, b) => a && b && b.length >= a.length && b.subarray(0, a.length).equals(a);
  ok("recorded chain: 10-07's cycles are an exact byte prefix of 10-08's, and 10-08's of 10-09's (append-only, as recorded)", pre(c7, c8) && pre(c8, c9) && c7.length < c8.length && c8.length < c9.length);
  const n = (b) => b.toString("utf8").split("\n").filter((l) => l.trim()).length, live = (b) => b.toString("utf8").split("\n").filter((l) => l.trim()).map((l) => JSON.parse(l)).filter((r) => r.live).length;
  ok("recorded rows: 6 / 30 / 52 cycle rows, every one live, every line parses", n(c7) === 6 && n(c8) === 30 && n(c9) === 52 && live(c7) === 6 && live(c8) === 30 && live(c9) === 52, `${n(c7)}/${n(c8)}/${n(c9)}`);
  { // the home-sourced 10-09 day against that evening's git snapshot (read-only git show): the snapshot is a superset, as appending implies
    let g = null, why = null; try { g = new Map(FILES.map((f) => [f, gitShow(SNAP_0909.commit, "backend/data/" + f)])); } catch (e) { why = e.message; }
    const d9 = days["2026-10-09"], gc = g && g.get("r309-cycles.jsonl"), gl = g && g.get("r309-ledger.jsonl"), gj = g && g.get("r309-surge-hold48.json");
    const ev9 = (b) => { try { const j = JSON.parse(b.toString("utf8")); return JSON.stringify([j.config && j.config.evidenceStart, j.read]); } catch { return null; } };
    ok(`recorded 2026-10-09 (home, the 13:08 MT pull) vs git ${SNAP_0909.commit} (${SNAP_0909.note}): the fixture's cycles are an exact byte prefix of the committed file (${c9.length} of ${gc ? gc.length : "?"} bytes, 52 of ${gc ? n(gc) : "?"} rows), the ledger equal (empty), evidenceStart and read equal, r309-interim.json absent in both`,
      g && gc && pre(c9, gc) && c9.length < gc.length && n(gc) === 54 && gl && gl.equals(d9.get("r309-ledger.jsonl")) && gj && ev9(gj) === ev9(d9.get("r309-surge-hold48.json")) && ev9(gj) === JSON.stringify(["2026-10-08", null]) && g.get("r309-interim.json") === null && !d9.has("r309-interim.json"), why || (gc ? `prefix ${pre(c9, gc)}, rows ${n(gc)}` : "no cycles at the commit")); }
  const ev = (d) => { const j = JSON.parse(days[d].get("r309-surge-hold48.json").toString("utf8")); return [j.config && j.config.evidenceStart, j.read]; };
  ok("recorded config: evidenceStart null on 10-07, '2026-10-08' on 10-08 and 10-09; no sealed read in any", JSON.stringify(ev("2026-10-07")) === JSON.stringify([null, null]) && JSON.stringify(ev("2026-10-08")) === JSON.stringify(["2026-10-08", null]) && JSON.stringify(ev("2026-10-09")) === JSON.stringify(["2026-10-08", null]), JSON.stringify([ev("2026-10-07"), ev("2026-10-08"), ev("2026-10-09")]));
  ok("recorded ledger: empty (0 bytes) on all three days — R309 had not traded; r309-interim.json absent on all three", ["2026-10-07", "2026-10-08", "2026-10-09"].every((d) => days[d].get("r309-ledger.jsonl") && days[d].get("r309-ledger.jsonl").length === 0 && !days[d].has("r309-interim.json")));
  let lc = null, lerr = null; try { lc = lifecycleBytes(buildLifecycle(c9)); } catch (e) { lerr = e.message; }
  const cur = fs.existsSync(path.join(FX, "lifecycle.json")) ? fs.readFileSync(path.join(FX, "lifecycle.json")) : null;
  ok("fixtures/lifecycle.json equals its rebuild from the recorded 10-09 cycles (deterministic), sha as indexed", lc && cur && lc.equals(cur) && sha(cur) === (idx.lifecycle && idx.lifecycle.sha256), lerr);
  if (cur) {
    const L = JSON.parse(cur.toString("utf8")), st = L.states;
    ok("lifecycle: 10 ledger states; statuses covered: submitting, submitted, open, submit-error, unfilled, exiting, not-sent, closed, error, plus a missed row", st.length === 10 && ["submitting", "submitted", "open", "submit-error", "unfilled", "exiting", "not-sent", "closed", "error"].every((s) => st.some((x) => x.rows.some((r) => r.status === s))) && st.some((x) => x.rows.some((r) => r.kind === "missed")));
  }
  return res;
}
function write() {
  const idx = { schema: "r309fold-fixtures-v1", note: "sha256 of every recorded fixture (byte copies) and of lifecycle.json; docs/server/wave-r309fold/fixtures.cjs --check", recorded: [], lifecycle: null };
  for (const R of RECORDED) {
    const dir = dayDir(R.day);
    if (!fs.existsSync(dir)) {
      for (const f of FILES) {
        const b = R.source === "git" ? gitShow(R.commit, "backend/data/" + f) : (fs.existsSync(path.join(REPO, "backend", "data", f)) ? fs.readFileSync(path.join(REPO, "backend", "data", f)) : null);
        if (b != null) atomicBytes(path.join(dir, f), b);
      }
      console.log(`wrote recorded/${R.day} (${R.source === "git" ? "git " + R.commit : "backend/data"})`);
    } else console.log(`kept  recorded/${R.day} (recorded data is never replaced)`);
    const m = readDay(R.day);
    idx.recorded.push({ day: R.day, source: R.source === "git" ? `git ${R.commit} (${R.note})` : R.note, files: Object.fromEntries([...m.entries()].map(([f, b]) => [f, { sha256: sha(b), bytes: b.length }])) });
  }
  const lb = lifecycleBytes(buildLifecycle(readDay("2026-10-09").get("r309-cycles.jsonl")));
  atomicBytes(path.join(FX, "lifecycle.json"), lb); idx.lifecycle = { sha256: sha(lb), bytes: lb.length };
  require(path.join(REPO, "backend", "lib", "atomic-write.js")).writeJsonAtomic(path.join(FX, "index.json"), idx);
  console.log("wrote lifecycle.json and index.json");
}

if (require.main === module) {
  const a = process.argv.slice(2).join(" ");
  if (a === "--write") { write(); process.exitCode = 0; }
  else if (a === "--check" || a === "--selftest") {
    const res = check(); for (const x of res) console.log(`  ${x.c ? "ok  " : "FAIL"} ${x.n}${!x.c && x.d ? " — " + String(x.d).slice(0, 300) : ""}`);
    const bad = res.filter((x) => !x.c).length; console.log(`fixtures selftest: ${res.length - bad} passed, ${bad} failed`); process.exitCode = bad ? 1 : 0;
  } else { console.log("usage: node fixtures.cjs --check | --selftest | --write"); process.exitCode = 2; }
}
module.exports = { RECORDED, FILES, readDay, buildLifecycle, signalFrom, check, dayDir, FX };
